mapper.select:
select wp.publisher_id,wp.publisher_name,count(id) as num from work_plan wp
where wp.deleted = 0

      and wp.publish_time >= #{param.period.begin}


      and wp.publish_time <= #{param.period.end}


      and wp.dept_id = #{param.deptId}

group by wp.publisher_id

select wp.dept_id,wp.dept_name,count(id) as num from work_plan wp
where wp.deleted = 0

      and wp.publish_time >= #{param.period.begin}


      and wp.publish_time <= #{param.period.end}

group by wp.dept_id
